<?php require __DIR__.'/bootstrap.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'&&$id!==user()['id']){$pdo->prepare("DELETE FROM users WHERE id=? AND role='student'")->execute([$id]);flash('Student removed.');}elseif($action==='save'){ $name=trim($_POST['name']??'');$email=trim(strtolower($_POST['email']??''));$course=trim($_POST['course']??'');$year=(int)($_POST['year']??0);if(!valid_name($name)||!filter_var($email,FILTER_VALIDATE_EMAIL)||$course===''||$year<1||$year>6){flash('Use valid student details.','error');}else{try{if($id){$pdo->prepare("UPDATE users SET name=?,email=?,course=?,year_of_study=?,status=? WHERE id=? AND role='student'")->execute([$name,$email,$course,$year,$_POST['status']==='inactive'?'inactive':'active',$id]);}else{$password=password_hash('Student@123',PASSWORD_DEFAULT);$pdo->prepare("INSERT INTO users(name,email,password_hash,role,course,year_of_study) VALUES(?,?,?,'student',?,?)")->execute([$name,$email,$password,$course,$year]);}flash('Student saved.');}catch(PDOException $e){flash('Email already exists.','error');}}} log_action($pdo,'student_'.$action,(string)$id);header('Location:students.php');exit;}
$q=trim($_GET['q']??'');$course=trim($_GET['course']??'');$sql="SELECT id,name,email,course,year_of_study,status FROM users WHERE role='student'";$args=[];if($q!==''){$sql.=" AND (name LIKE ? OR email LIKE ? OR course LIKE ?)";$like='%'.$q.'%';$args=[$like,$like,$like];}if($course!==''){$sql.=' AND course=?';$args[]=$course;}$sql.=' ORDER BY name';$s=$pdo->prepare($sql);$s->execute($args);$rows=$s->fetchAll();if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=students.csv');$out=fopen('php://output','w');fputcsv($out,['Name','Email','Course','Year','Status']);foreach($rows as $r)fputcsv($out,$r);fclose($out);exit;}$courses=$pdo->query("SELECT DISTINCT course FROM users WHERE role='student' AND course IS NOT NULL ORDER BY course")->fetchAll();page_top('Student management');?>
<h1>Student management</h1><section class="grid two"><form class="panel form-grid" method="post"><h2>Add student</h2><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="save"><label>Name<input required name="name"></label><label>Email<input required type="email" name="email"></label><label>Course<input required name="course"></label><label>Year<input required type="number" min="1" max="6" name="year"></label><button>Add student</button><p class="muted">New accounts use temporary password: Student@123</p></form><form class="panel form-grid" method="get"><h2>Search and filter</h2><label>Search<input name="q" value="<?=e($q)?>" placeholder="Name, email, course"></label><label>Course<select name="course"><option value="">All courses</option><?php foreach($courses as $c):?><option <?=($course===$c['course'])?'selected':''?>><?=e($c['course'])?></option><?php endforeach;?></select></label><button>Apply</button><a class="button secondary" href="students.php?export=csv">Export CSV</a></form></section><section class="panel table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Course</th><th>Year</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e($r['course'])?></td><td><?=e((string)$r['year_of_study'])?></td><td><?=e($r['status'])?></td><td><form class="inline" method="post" onsubmit="return confirm('Remove this student?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></section><?php page_bottom();
